        HelpEntry(
            id = "money",
            title = "Money",
            keywords = listOf("money", "under usual", "over usual", "compared with usual", "category against usual", "total card", "across my accounts", "cash trading and cards", "owed on cards", "biggest idea", "lead idea", "brass card", "money on the open fold", "two columns", "money on the mac", "money tabs on the side", "wide screen money", "ask obi", "obi money chat", "money chat", "ask obi about my money", "what if i save a month", "can i afford a holiday", "obi's money check", "ask obi to look again", "written by obi", "obi's words for the ideas", "money check", "ideas to save", "save money ideas", "remind me about an idea", "not for me", "card interest leak", "accounts foot", "where does net worth come from", "plan tab", "what if row", "set a challenge", "plan foot", "about these numbers", "where do the numbers come from", "info button", "money goals", "goals on plan", "saving goal pace", "am i on track to save", "how much a month for my goal", "clear my cards", "pay off my cards", "card debt", "debt-free date", "which card to pay first", "card apr", "what if I save", "savings plan", "save each month", "saving goal", "my accounts", "account list", "remove an account", "mark a card", "budget my own category", "cap my category", "my categories in plan", "halve my own category", "ideas for my own category", "monthly cap", "payment sheet", "needs vs wants", "needs and wants", "need or want", "essentials", "mark as a need", "new category", "my own category", "rename a category", "delete a category", "merge categories", "hide a category", "your categories", "manage my categories", "custom category", "add a category", "make a category", "change a payment's category", "recategorise", "move payments to another category", "receipts in money", "receipt for a payment", "receipt detail", "month in review", "money review", "how did last month go", "last month's spending", "monthly review", "year in review", "money year in review", "my year in money", "spending this year", "what did I spend this year", "paying abroad", "which card abroad", "card to use abroad", "spending abroad", "holiday money", "travel money", "non-sterling fees", "spending challenge", "money challenges", "no-spend days", "no spend day", "fun money", "spending cap", "category cap", "budget for a category", "cap my spending", "shared costs", "who paid what", "split the bills", "settle up", "what my wife paid", "what my partner paid", "joint spending", "side hustle", "business income", "business email invoices", "invoices in my business mail", "self assessment", "set aside for tax", "year-end export", "accountant spreadsheet", "tax year", "trading allowance", "big order alert", "funding alert", "funding costs", "net worth", "what am i worth", "my net worth", "what i own and owe", "pension value", "savings elsewhere", "loans and debts", "credit card", "card due", "card payment", "charge card", "minimum payment", "credit limit", "card limit", "0% ends", "zero percent", "interest charged", "payday", "safe to spend", "until payday", "low balance", "refunds on the way", "refund not arrived", "chase a refund", "money forecast", "savings forecast", "left over each month", "money tips", "worth a look", "money notifications", "money alerts", "money heads-up", "double charge", "charged twice", "unusual payment", "foreign transaction fees", "late fee", "regular payments", "subscriptions total", "price rise", "spending habits", "money manager", "spending", "my spending", "what did i spend", "spending by category", "categories", "bank statement", "import a statement", "statement file", "csv statement", "bank csv", "transactions", "delete money data", "export my payments", "payments csv", "rename an account", "name an account", "connect my bank", "open banking", "lunch flow", "bank sync", "refresh my bank", "reconnect my bank", "trading tracker", "hyperliquid", "hyperliquid address", "am i making money trading", "trading profit and loss", "my trading pnl", "trading win rate", "best trade", "worst trade", "trading fees", "funding paid", "which coin makes money", "open positions", "liquidation", "liquidation alert", "near liquidation", "trading alert", "drawdown", "down from the high", "trading drop alert", "equity curve", "trading chart", "pnl chart", "trading over the month", "is my trading going up", "trading in net worth", "hyperliquid in pounds", "dollar rate", "trading in gbp", "trading on today", "trading in my brief", "equity card", "1d 1w 1m", "trading tiles", "closed profit", "winning trades", "alerts sheet", "trading this week", "trading today", "export my trades", "trades for tax", "trading tax", "crypto tax", "tax year trades", "trading spreadsheet", "trades csv", "for my accountant", "trades in pounds", "hmrc exchange rate", "hmrc rates", "monthly trading review", "last month's trading", "how did my trading go last month", "trading month in review", "trading in the forecast", "trading what if", "trading income forecast", "trading in pounds", "show trading in pounds", "trading in dollars", "dollars or pounds", "ask about my money", "ask about my spending", "can i afford", "what's coming out", "money questions in talk"),
            what = "your spending by category, month by month, from the statements of your bank and card accounts, kept behind your fingerprint (Touch ID on the Mac). Read-only: Navilife never moves money, pays anything or keeps a bank password, and nothing it shows is financial advice.",
            how = "Download a statement from your bank's website or app as CSV (some call it a spreadsheet or Excel file). Open Ask → Life → Money, confirm it's you, go to Accounts and tap Import, export and delete (under MORE), type which account it is (e.g. Current account) and tap Import a statement file, then pick the file. Importing the same months again adds nothing twice.",
            tips = listOf("To add a statement to an account already there, tap it under ACCOUNTS and choose Import a statement into it.", "Each month shows what you spent, what came in, and each category with its share of the month; for a finished month it says how that compares with your average over the 6 months before, and lights a category that's well over it. Use ‹ and › to go back a month or forward again.", "A payment in the wrong category? Tap it (click on the Mac): its sheet shows the payee and your categories as chips, the ones you use most first. Pick the right one and every payment from that payee moves there, past and future (\"Moved 14 payments from … to …\", with Undo), on the Fold and the Mac alike. Need, Shared, Always shared and Side hustle sit below; Done closes it.", "Each category on Spending says how it compares with your usual month: \"£20 under usual\" in green, \"£110 over usual\" in amber, or \"as usual\". This month compares with your usual pace by today (from the 7th). The same on the Mac.", "Bills, subscriptions and fees go out in lumps, so this month they only say over once past a whole usual month. With one month before, a note names it (\"£20 under September\"); with none, it counts the payments.", "Lots of payments in Other? Under Spending's categories, \"52 payments without a category · Sort them\" opens a quick sorter: one payee at a time, the biggest first. Tap a category and every payment from that payee moves there, past and future (Undo under the chips), and the next payee comes up at once; Skip leaves one for later, + New category makes one of your own. The same on the Mac.", "On Spending, the chips over the category rows (beside All) switch between Categories and Needs vs wants, which splits the month in two (groceries, bills, transport, fuel, home, health, the kids and fees are needs; the rest wants) and names each side's biggest categories.", "A payee in the wrong half? Tap one of their payments and switch Need on or off: every payment to them moves, past and future (with Undo), on the Fold and the Mac alike. No total changes.", "Want a category of your own (Vape, Dog, Hobbies)? Tap a payment, then + New category at the end of the chips: type its name, pick a colour and an icon, and tap Create. That payee's payments move into it, past and future (\"Made Vape · moved 14 payments from …\", with Undo), it gets its own row and slice on Spending, and its chip comes first next time, on the Fold and the Mac alike.", "Your own categories live in Money → Accounts under YOUR CATEGORIES. Tap one to rename it or change its colour and icon (Save), Hide from the ring (its slice turns grey like Other, its row stays), merge it into another category (its payees move there, past and future), or Delete category: it asks first, then its payees go to Other. Every change has Undo and shows on the Fold and the Mac alike.", "A monthly budget on a category of yours? Money → Accounts → YOUR CATEGORIES, tap it and type an amount under MONTHLY CAP (e.g. £60): its sheet and row show this month against it (\"£17.50 of £20 · £2.50 left\"), and it joins CHALLENGES and Goals' streaks. \"Vape £60\" in the challenges' cap field works too. Remove takes it off, with Undo, on the Fold and the Mac.", "A card statement that lists purchases as positive amounts is read the right way round (purchases as money out); the line after an import says so.", "Money → Accounts lists each account once, by a short name (\"HSBC current\"), with its balance (a card's as owed) or Add balance. Tap one for its sheet: give it your own name under Name (\"Joint bills\"; clear it for its own name), type its balance, switch It's a card or Side hustle account, or import a statement into it. Your name for it shows on Accounts, Bills and card reminders.", "Remove account in an account's sheet asks first, then takes it and its transactions off every device; Delete all money data (Accounts → MORE → Import, export and delete) asks first, then clears everything. Your bank keeps its own records.", "From your banks: your accounts and cards fill Money by themselves through Lunch Flow, read-only, every few hours. Refresh fetches them now (it takes a minute), and so does the Updated pill beside the title; the line says when they were last fetched and how many accounts.", "A bank asks you to agree again every 90 days or so: Money then says \"Reconnect … in Lunch Flow\" and Open Lunch Flow takes you there. Navilife never logs in to your bank and never moves money.", "A statement you imported before for the same account counts once: its lines that match the bank's are left out, and its balance isn't added twice. A bank account you Remove stays off until you tap Sync them again.", "On the open Fold each Money tab uses the wide screen in two columns, as in the design: on Spending the ring and its tiles on the left, the categories and latest payments on the right; Bills, Plan, Trading and Accounts split the same way. Folded, it's one column.", "On the Mac, once Money is unlocked its window widens: the five tabs run down the left under MONEY and each tab sits in the same two columns, as in the design.", "Ask Obi sits under the tabs on every Money tab: tap it and ask “Can I afford a £1,200 holiday in July?”, “What if I save £300 a month for 6 months?” or “Which card should I pay off first?”. Obi works out the sums on the device, with Make it a goal, Use this plan or Show the numbers under the answer; the Try questions are made from your money.", "Ask Obi anything else about your money (“Is coffee becoming a habit?”, “Why was September so expensive?”) and his AI answers from your last three months' totals by category, your biggest payees and what's still to go out, never your accounts or balances. \"Obi's answer · from your monthly totals and payees\" sits under it; an answer with a figure that isn't in your numbers is never shown.", "The mic at the end of the Ask Obi bar opens Obi · money already listening: say “Can I afford three hundred pounds on Saturday?” and he answers as if you'd typed it (on the Mac, Dictation listens into the field; press Return). The mic beside the field listens again; tap it while you speak to finish. Nothing is recorded or kept.", "Plan starts with Obi's money check in a brass-edged card: what its ideas could save a year (\"£908 a year, from 4 ideas\"). The biggest idea has its own card with why, its step, Remind me and Not for me; the others sit on one line each (card interest, a price rise, a habit, subscriptions, a category over usual). Tap an idea's name for the payments behind it.", "In an idea's sheet, Remind me puts it away for 2 weeks and Not for me for good, both with Undo, on the Fold and the Mac alike; \"2 put away · Show them again\" brings them back. Ideas come only from your own payments; nothing is moved, cancelled or paid.", "Once a week Obi reads the ideas and puts them in his own words, most worth your attention first (\"Written by Obi · Sun 25 Oct\" under them); Ask Obi to look again asks him now. He only sees the ideas, their figures and the payee names and amounts behind them, never your accounts or balances, and his words use only those numbers, or the plain ones stay.", "Regular payments lists what's taken about once a month for about the same amount (subscriptions, the gym, bills), with when it was last taken, when it's next due and the monthly and yearly total.", "Worth a look on Spending lists payments that deserve a second look, one line each with the amount: the same amount at the same shop twice within a day, a payment much bigger than usual or a first big one somewhere new, and fees (foreign, late, interest). Three show, then \"2 more ›\"; tap one for when and where.", "Not you? Your bank's app can stop or dispute it; Navilife never acts on your accounts. That's fine (or a swipe either way on the Fold) puts an alert away on both devices, with Undo.", "You don't have to open Money to find them: when this week's payments make something worth a look (a double charge, a big or new payment, a fee) or a new tip, a heads-up comes from 09:00 naming what and where, never the amount; tap it to open Money.", "An old statement never sets one off, and each comes once (a tip once a month). Turn them down in Settings → Notifications → Money: worth a look and tips from your numbers, or hide a kind of tip.", "What if I save… on Plan: slide an amount a month (£25 steps), pick 3, 6, 12 or 24 months and no interest or a rate to compare, and the bars, the total and the month it's reached update as you go, with what's left of your average month and Obi's line on whether it fits. Make it a goal puts it in Goals with that month as its date (Undo). Sums, not advice; nothing moves.", "Clear my cards on Plan lists your credit cards with what each owes and its rate (charge cards are paid in full, so they're left out). Slide one amount a month for all of them and pick Highest interest first or Smallest balance first: each card says when it's clear, with the month you're debt-free and the interest you'd still pay.", "Under the tiles: what paying only the minimums would mean, and Obi's line on which order costs less and whether the amount fits your usual month. Use this plan puts \"Clear my cards by …\" in Goals with that month as its date (Undo).", "A card's rate is the APR you type in its sheet on Bills (tap the card, then APR, e.g. 24.9%); until then it's worked out from the last interest charged on its statement (\"about\"), or shown as APR ? and counted as nothing. Sums, not advice: Navilife never pays anything.", "Forecast at your pace takes your average whole month (what comes in, what goes out, what's left over) and says where that leaves you in 6 and 12 months. It needs two whole months of statements; it's an average, not a promise, and not financial advice.", "Your own categories count in Plan too: a want of yours bought often (\"Vape 10× in 30 days\") or well over its usual this month is one of Obi's ideas, with Set a cap, and \"Halve Vape\" can be one of the what-ifs.", "What if: tap Halve on one of your biggest everyday categories, or type an extra amount a month (£200, £50 a week, £1,200 a year), and the 6- and 12-month lines say how much more it would leave you. What-ifs stay on the device you're using and go when Money locks.", "With a Hyperliquid address followed, What if also offers Trading as it's gone: your actual trading result a month (last month and the one before, after fees and funding, in pounds at today's rate; the last 30 days until the month is added up). Tap it and the 6- and 12-month lines add it on top of your statements, a loss as a loss.", "Refunds on the way on Bills is one card of short rows, each refund and where it stands (\"Back · +£40\", \"Waiting · 5 days\", \"Late · 16 days · chase it\"); three show, then \"2 more\".", "Tap a refund for its sheet: when the shop's money is back, Close it takes it off Waiting for (Undo). Two weeks on with nothing back, it lights and drafts a chase; Copy the chase puts it on the clipboard for you to send in the shop's chat or email, and marks it chased. Navilife never sends it.", "Plan is in cards too: Obi's money check leads with its total, then the biggest idea's own card and one-line rows for the rest (then \"2 more\"), each opening a sheet. The forecast's what-ifs sit behind its What if… row, and fun money or a category cap behind Set a challenge, each in a sheet.", "Plan ends on one line, \"Read-only · not financial advice\"; its ⓘ says how What if I save, Clear my cards, the forecast, the challenges and paying abroad are worked out.", "Trading shows your equity, open positions (five, then \"See all\"), the P&L line, your trades, the month in review, your addresses, alerts and the tax export as one card each, with a Read-only mark on the equity card, and ends on one line, \"Read-only · not trading advice\"; its ⓘ says where the figures come from and how trades are counted.", "Under the equity card, the last 30 days sit in four tiles: closed profit, funding paid (or received), fees and winning trades (\"14 of 23\"); Your trades then shows what's left after fees and funding and each coin.", "Accounts opens on one total card: \"Across 6 accounts and trading\" over the total and one line of what's in it (cash · trading · owed on cards · outside these accounts), with the month-by-month line under it. In the list, what a card owes is in amber and an account with no balance says Add balance quietly; tap it to type one.", "Accounts shows your banks, net worth and the year in review as one card each, and ends on the same one line; its ⓘ says where the accounts, your banks, net worth and the year come from.", "Bills lists the month's bills in one card, five then \"See all\", and ends on one line, \"Read-only · not financial advice\"; its ⓘ says where the bills, cards and refunds come from.", "Ask or Talk about your money: \"how much did I spend on takeaways last month?\", \"what's coming out this week?\", \"when's payday?\", \"can I afford £300 on Saturday?\". It's answered on the device from Money, never sent to the AI.", "While Money is locked, a money question shows Unlock Money to answer: your fingerprint (Touch ID on the Mac), then the answer; for five minutes after, money questions (Talk's follow-ups too) are answered straight away.", "Until payday finds your payday from your pay coming in (two months or more of the account it goes into) and says what you've spent since and what's still to go out before it: regular payments, and the bills, subscriptions and club fees with a cost on Lists → Renewals.", "With that account's balance it says what's safe to spend until payday, and a day, and lights when it's tight. A statement file with a Balance column gives it, or type it under Until payday (−£50 if overdrawn).", "Cards: on Accounts, tap the card's account and switch on It's a card. On Bills each card is one row (\"Due ? · tap to add\" until its due day is in); tap it to type what its statement says: the statement balance, the minimum, the day of the month it's due, the limit and when a 0% period ends, or to mark it Paid.", "Until payday on Bills is one row: tap it for since payday, the pay account's balance (type it there) and what's safe to spend.", "Each card says when it's due (lit three days out), \"pay in full to avoid interest\" (a charge card is paid in full), how much of the limit the statement uses (lit from 75%) and any interest or late fee charged on it.", "Three days before a card payment, at 9 in the morning, a heads-up says it's due (no amounts on the lock screen). Tap Paid on the card once you've paid it and the reminder stops until next month (Undo).", "A 0% period gets a heads-up a month and a week before it ends. A card due before payday counts in what's still to go out. Navilife never pays anything.", "Net worth adds up each account's balance, what each card's statement says you owe, and things you type that aren't in these accounts: \"Pension £42,000\", \"Savings elsewhere 12k\", \"Car £8,500\", \"Car loan £3,200\" (a loan, mortgage, debt or a minus sign counts it as owed). They live behind Outside these accounts on Money → Accounts; type the same name again to update one; Remove takes one off (Undo).", "A card always counts as owed: its statement, else its balance.", "An account with no balance isn't counted yet and the total says \"Partial\": type its balance in the field under it. The line under the total shows the last 12 months, each account's balance worked back through its statements (cards and what you typed stay at today's figures); tap a month for its total. Not financial advice.", "Trading: under YOUR ADDRESSES tap Add an address and type your Hyperliquid public address (the 0x… one, never a key) in its sheet, with a name if you like (\"Main 0x…\"). Nothing here can trade; Remove stops following an address. Under it, YOUR TRADES adds up the last 30 days: trades closed and how many won, fees and funding, the best and worst trade and each coin's result after fees.", "Trading alerts: under ALERTS in Money's TRADING, tap the one row (it says how many are on) and, in its sheet, pick how near liquidation a position may get before Navilife alerts you (10% unless you change it; this one comes even in quiet hours) and how far below this month's high an account may fall before a heads-up (20%). The alerts never show amounts; tap one to open Money.", "Two more trading alerts under ALERTS: A big order (a heads-up when one order is worth 5× the account unless you choose 2× or 10×, within two hours of it filling) and Funding paid in a day (a heads-up once a day when the last 24 hours' funding costs 1% of the account, or 0.5% or 2%). Both are measured against the account, so no amounts are shown.", "Money's Trading leads with your equity card: \"Hyperliquid · Main 0x…\" with the Read-only mark, the value with about what it is in pounds beside it, how it changed and its line. Tap 1D, 1W or 1M under the line for today, the week or the month; the grey line under them says all time and when it was read.", "Your Hyperliquid accounts count in Accounts' total in pounds, at the European Central Bank's daily dollar rate (the row says the rate and its day), and the trading equity says \"about £…\" beside the dollars.", "Today's header says \"Trading · up today · 2 positions open\" (no amounts: the figures stay in Money), lit when a position is near liquidation or an account is at your drop level; the morning brief says the same in a sentence (the Short brief only when it's lit).", "EXPORT FOR TAX under Money's TRADING saves a spreadsheet (CSV) of a UK tax year (6 April to 5 April): every order with its size, average price, value, closed profit and loss and fee, each day's funding per coin, and each account's totals. Tap the year, wait while Navilife's server reads it from Hyperliquid (up to a minute), then choose where to save it. Facts only, not tax advice.", "The tax export gives US dollars and pounds: each row is also converted at HMRC's monthly exchange rate for its month, shown in its own column. A month whose rate couldn't be read is left blank and the file says so.", "From the 1st of each month Money's TRADING shows last month in review: trades closed and won, the result after fees and funding, against the month before, the best and worst coin, the biggest win and loss. A heads-up at 9:00 on the 1st says it's ready (no amounts). From Hyperliquid's public data, UK months, perpetuals only; facts, not advice.", "Navilife's server reads each address from Hyperliquid's public data every few minutes while a position is open, hourly otherwise: equity, profit and loss for today, the week, the month and all time (deposits and withdrawals aren't counted as profit), and each open position with how far it is from liquidation (lit within 10%).", "Tap \"≈ £…\" beside the equity on Money's Trading to see Trading in pounds, and \"≈ \$…\" to go back to dollars. In pounds every amount on Trading is shown at the European Central Bank's daily dollar rate; prices stay in dollars, as Hyperliquid quotes them. The choice follows you on both devices.", "Under the equity on Money's TRADING, Obi says your risk in a line: what share of everything you hold is trading, how far the price can move before your nearest position's liquidation (lit when it's close), and what funding has cost or paid you in the last 30 days.", "Below the open positions on Money's TRADING, KESTREL shows what Kestrel has asked: a trade waiting for your OK, what it wants to do and when it expires, and today's tally; Review in Needs you takes you to the request, where a yes still needs your fingerprint (Touch ID on the Mac). Nothing on Trading can trade.", "Side hustle and tax (Money → Accounts → MORE) adds up your side hustle for the UK tax year so far (from 6 April): what came in, what went out by category, and the profit. On Accounts, tap the account its money goes through and switch on Side hustle account, or tap a payment and switch on Side hustle (every payment to or from them counts, on any account).", "Under SIDE HUSTLE AND TAX pick the share of the profit to put aside (10% to 40%); it's your choice, not a tax bill. The next Self Assessment dates are listed, lit within a month. Not tax advice: Navilife never files or pays anything.", "Under SIDE HUSTLE AND TAX, FROM YOUR BUSINESS EMAIL lists this tax year's payments to you and costs that emails in your Business mail account name (read from the subject and preview only), each checked against your statements: counted, not counted as business yet (tap Business to count its payer), or lit when it should be there by now. Only your statements count in the profit.", "Under SIDE HUSTLE AND TAX, YEAR-END EXPORT saves a spreadsheet (CSV) of a tax year's side hustle money for your accountant: every payment in and out with its account and category, then money in, money out by category and the profit. It's made on your device from your own statements; tap last year or this year so far, then choose where to save it.", "Shared with (your partner's name from About you; Money → Accounts → MORE) keeps a running who-paid-what. Tap a payment and choose Shared for just that one, or Always shared for every payment there (the weekly shop, the energy bill); type what they paid below (\"Tesco £42.50\"). It says who owes whom at the share you pick (half each unless you choose 40, 60 or 70%).", "Export all payments: Money → Accounts → MORE → Import, export and delete → Export all payments (CSV) makes a spreadsheet of every payment Navilife has (date, account, words, category, money in or out) on the device and asks where to save it. Nothing is sent anywhere.", "Settled up starts the count again: only what's paid after it counts (Undo puts it back). Navilife never moves money or asks anyone to pay; income and transfers are never counted as shared.", "CHALLENGES in Money (this month) are goals you set yourself from your own statements: No-spend days counts the days with no everyday spending (bills, subscriptions and fees don't break one), with a dot per day, the streak and your best this month.", "Fun money gives you an allowance for the week, Monday to Sunday (\"£50\"), for eating out, coffee, takeaways, going out, shopping and clothes; a cap limits one category for the month (\"Eating out £150\", \"Takeaways £60\"). Each shows a bar, what's left (brass from 90%) and how many weeks or months in a row you stayed within it. Remove takes one off (Undo); they follow you on both devices.", "PAYING ABROAD in Money (this month) looks at the last year of your statements: payments in another currency (a line with EUR, USD, € or a Visa rate) and the foreign fees charged for them, per account. It says which card charged no foreign fees, which did and about what share, and the one to use abroad.", "When your phone or Mac is in another time zone, or a trip on Trips starts within two weeks, the card to use leads the top of Money. Ask \"which card should I use abroad?\" for the same answer, on your device. It's from your own statements, not a product suggestion or financial advice.", "The month in review in Money is one card: Spent, Came in and Left, and at most two short lines (against your usual, and what moved most). Its ⓘ tells the rest in plain sentences: where most went, a new place you paid, the biggest payment, the days with no everyday spending and, with a side hustle marked, what it made.", "Page back (‹) to any finished month to read its own; for the first ten days of a month last month's leads, and a heads-up on the 2nd at 09:00 says it's ready (no amounts). Worked out on your device, nothing sent; not financial advice.", "Spending ends on one line, \"Read-only · not financial advice\"; its ⓘ says where the numbers came from (your banks through Lunch Flow, your statement files, or both) and that transfers between your accounts are left out.", "The year in review is on Money → Accounts, under net worth: it shows what you spent and what came in over the year, each category with its share, against the same dates the year before when your statements reach back that far, the busiest and quietest months and the biggest payment. Tap Open to unfold it.", "In January it shows the year just finished, already open, and a heads-up on 2 January at 09:00 says it's ready (no amounts in the notification); the rest of the year it shows this year so far. Transfers between your accounts aren't counted as spending. Not financial advice.", "GOALS on Plan lists your goals with a £ number from Goals (\"Save £2,000 for the holiday\", or one made from What if I save…): each with what's in, a bar and one line on its pace, \"£180 a month to 15 Dec · on track\", in amber when it's behind (\"£60 behind\"). With no date it says what's left to go.", "Tap a goal for its sheet: tap an account there and the goal follows that account's balance, so its number, chart and pace in Goals move as the savings do, with nothing to type. Tap the account again to stop (the number stays where it got to).", "A goal that follows an account is brought up to date each time you open Money (and when you import a statement or type a balance there), and its amount then shows in Goals, outside Money's lock. Cards can't be followed; an account with no balance yet waits until you type one in its sheet on Accounts.", "A payment in Money shows what it was for when Navilife tidied its receipt or order email: \"Receipt in your email · “Your Currys order”\" and the email's preview line under it (the same amount, from the day before the email to five days after, the shop's name in the statement's words). The month says how many of its payments have one. Nothing is read from the email's body and nothing is sent."),
            fold = HelpPlace.MONEY,
            foldWhere = "Ask → Life → Money",
            mac = HelpPlace.MONEY,
            macWhere = "Ask → Life → Money",
            macHow = "Open Ask → Life → Money, confirm with Touch ID, go to Accounts and click Import, export and delete (under MORE), type which account it is and click Import a statement file…, then choose the CSV file you downloaded from your bank (or click an account under ACCOUNTS → Import a statement into it…).",
            data = true,
        ),
