        HelpEntry(
            id = "reading",
            title = "Reading",
            keywords = listOf("reading", "reading list", "reading and learning", "books to read", "book list", "podcasts to get to", "courses", "online course", "how far through", "finished a book", "up next to read", "reading goal", "books this year"),
            what = "the books, podcasts and courses you want to get to, with how far you are through each one you've started.",
            how = "Type one line, e.g. \"Atomic Habits by James Clear, 320 pages\", \"podcast The Rest Is History\" or \"course Kotlin coroutines 12 lessons\", and press Done: it goes under UP NEXT. Start puts it ON THE GO; type how far you've got under it (\"120\", \"p 120 of 320\", \"45%\", \"episode 4\", \"lesson 3\").",
            tips = listOf("Typing the last page (or 100%) finishes it; Finished and Put down move it off the go, and Remove takes it off. Each has Undo.", "Start a line with \"reading\" (\"reading Dune by Frank Herbert\") and it goes straight on the go.", "Once anything moves in a month, the top of Reading says what you finished and what's next up.", "Ask or tell Talk \"what am I reading?\" for the list, or just say how far you've got: \"I'm on page 200\", \"I'm halfway through Dune\", \"I've finished Atomic Habits\", \"add Dune to my reading list\". It's done at once with Undo, without the AI (Ask first in What Navilife may do makes it a card).", "Share a book, podcast or course from another app (Goodreads, Audible, a bookshop, a podcast app, Udemy…) to Navilife: the sheet offers \"📖 Add to Reading · …\" and puts it under UP NEXT. On the Mac, select a title or link and choose Services → Add to Navilife Reading.", "Under READING GOAL type how many books you'd like to finish this year (\"12\" or \"24 books\"): Reading and Goals show how many you've finished and whether you're on pace. Type \"none\" (or Clear the goal) to drop it.", "On an office day's commute the book (or podcast or course) on the go joins Today's train line with how far you are: \"… · Dune at 37%\"."),
            fold = HelpPlace.READING,
            foldWhere = "Ask → Daily → Reading",
            mac = HelpPlace.READING,
            macWhere = "Ask → Daily → Reading",
            macHow = null,
            data = true,
        ),
