        HelpEntry(
            id = "review",
            title = "Review",
            keywords = listOf("review", "weekly review", "my week", "prevented misses", "reflection", "weekly reflection", "reflect", "reflect on my week", "look back", "journal", "what went well", "what to drop", "one thing that matters", "life balance", "work life balance", "balance view", "time across work and family"),
            what = "your week looked back on: what got done, habits, and the misses Navilife helped prevent, with a two-minute reflection kept as a dated journal.",
            how = "Open it any time; the arrows step back through earlier weeks.",
            tips = listOf("Reflect (near the top) is a two-minute look back: what went well, what to drop, and one thing that matters next week. It opens by itself from Sunday 18:00 (or the time you choose) through Monday; any other time tap \"Reflect on your week\".", "The chips under each question come from your week (wins, things you ticked off, habits met, what's still open, your goals): tap one to add it. Type or use the keyboard's mic, then Save. One line in any of the three is enough.", "Saving keeps it in \"Your reflections\" (open it from an earlier week), adds what went well to Wins (untick \"Also keep in Wins\" to stop that) and, if you tapped a goal's chip for the one thing, makes it one of next week's goals. \"Skip this week\" puts it away until next Sunday.", "Say \"reflect on my week\" to Talk (on the phone or the Mac) and Review opens on this week (last week on a Monday) with Reflect open, any day. Nothing is kept until you tap Save.", "The one thing you said matters shows under Today's header all the next week (\"This week's one thing · …\", in brass on the Monday), and the morning brief says it on Monday (and every weekday on Standard and Full).", "To have the review and reflection come at another time on Sunday, tap Change beside \"Comes on Sundays at 18:00\" at the bottom of Reflect (on the Mac, pick the time there) and choose 16:00 to 21:00. The review's heads-up and Today's card move with it, on both apps.", "Not now on a Sunday? Tap \"Later tonight\" on Today's review card or on its notification: the card steps away and the review comes back two hours on (never after 22:00), on the phone and the Mac.", "Balance (under the numbers) shows the week's time across work, family, health and yourself against your targets, from your calendar, your work hours and the habits you ticked. Targets › sets each one (Your hours for work); they follow on both apps. Under each area four small bars show the last four weeks (brass when met) with how often you met it and your usual week.", "When family, health or your own time is well short of its target even with what's still planned, one heads-up comes on Thursday at 17:00, once a week at most; lower or silence it in Settings → Notifications under Balance.", "An event Balance can't place (\"N events not counted\") is listed under it with Count as: Family, Health, Self, Work or Don't count. Every event with that title counts that way from then on, past weeks too, on both apps; Undo puts it back, and Targets › lists your choices with Forget."),
            fold = HelpPlace.REVIEW,
            foldWhere = "Ask → Daily → Review",
            mac = HelpPlace.REVIEW,
            macWhere = "Ask → Daily → Review",
            macHow = null,
            data = true,
        ),
        HelpEntry(
            id = "school",
            title = "School",
            keywords = listOf("school", "school holidays", "half term", "inset", "inset days", "inset day", "term dates", "pe kit", "pe day", "school emails"),
            what = "the children's days off, PE and non-uniform days, trips and payments, with \"who's covering?\" a week ahead on office days.",
            how = "Tap Fill in under Holidays from the council for the council's term dates, then paste the school's INSET days or type them, e.g. \"INSET 4 Jan\".",
            tips = listOf("The council's dates say \"check with the school\"; days you type always win.", "Add the school's website in About you and School links to it.", "Add the addresses the school writes from under School's email in About you: its trips, payments, forms and days off then show in Needs you with Add, and Add puts them in School.", "A request with no date of its own, like \"please send in a named coat\", shows there too; Add makes it a task for the next school morning, not a School date.", "When the school writes that PE (or swimming, forest school, library books) is on certain days each week, each day shows there too; Add puts it in School as a weekly day, so Kids shows \"PE kit\" the day before."),
            fold = HelpPlace.SCHOOL,
